  await c.next((m) => m.type === 'enter_system', 'enter_system (home)');
  if (player.homeSystemId !== systemId) {
    c.send('warp', { destinationSystemId: systemId });
    await c.next((m) => m.type === 'warp_arrived', 'warp_arrived', 15_000);
  }
}

